+/**
+ * Install the {@link EchoReactiveHandler} singleton used by the prototype accessors.
+ * Called once by the echo-handler module at load time.
+ */
+export const setEchoHandler = (handler: EchoReactiveHandler): void => {
+  installedHandler = handler;
+};
+
+const handler = (): EchoReactiveHandler => {
+  invariant(installedHandler, 'EchoReactiveHandler not installed');
+  return installedHandler;
+};
+
+const getter = (get: (this: any) => any): PropertyDescriptor => ({ enumerable: false, configurable: true, get });
+
+const accessor = (get: (this: any) => any, set: (this: any, value: any) => void): PropertyDescriptor => ({
+  enumerable: false,
+  configurable: true,
+  get,
+  set,
+});
+
+const method = (value: (this: any, ...args: any[]) => any): PropertyDescriptor => ({
+  enumerable: false,
+  configurable: true,
